public class CollidingPointer {
    /**
     * 两数之和 II（有序数组），LeetCode 167
     * 数组升序，返回 1-indexed 的两个下标
     * 时间 O(n)，空间 O(1)
     */
    public static int[] twoSumII(int[] numbers, int target) {
        int left = 0, right = numbers.length - 1;
        while (left < right) {
            int sum = numbers[left] + numbers[right];
            if (sum == target) {
                return new int[]{left + 1, right + 1}; // 1-indexed
            } else if (sum < target) {
                left++;  // sum 太小，左端右移增大
            } else {
                right--; // sum 太大，右端左移减小
            }
        }
        return new int[]{-1, -1};
    }

    /**
     * 盛水容器，LeetCode 11
     * 移动短板那一端：长板侧不可能产生更大面积
     * 时间 O(n)，空间 O(1)
     */
    public static int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxArea = 0;
        while (left < right) {
            int area = Math.min(height[left], height[right]) * (right - left);
            maxArea = Math.max(maxArea, area);
            // 移动短板端：长板端移只会让宽度变小且 min 不增
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }
        return maxArea;
    }

    /**
     * 有效回文串，LeetCode 125
     * 跳过非字母数字字符，大小写不敏感比较
     */
    public static boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++;
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--;
            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

public class FastSlowPointer {

    // ===== 链表结构问题 =====

    /**
     * 环检测，LeetCode 141
     * fast 每次 2 步，slow 每次 1 步，有环必相遇
     */
    public static boolean hasCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }

    /**
     * 找环入口，LeetCode 142（Floyd 判圈法）
     * 相遇后一个指针回到 head，两指针同速走，再次相遇即入口
     * 数学：a = (n-1)c + (c-b)，a 是头到入口距离
     */
    public static ListNode detectCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) { // 相遇
                slow = head;    // slow 回到起点
                while (slow != fast) {
                    slow = slow.next;
                    fast = fast.next; // 同速走
                }
                return slow; // 再次相遇点 = 环入口
            }
        }
        return null;
    }

    /**
     * 链表中点，LeetCode 876
     * fast 到终点时 slow 恰好在中点
     * 偶数长度返回中间偏右节点
     */
    public static ListNode middleNode(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    // ===== 数组原地覆盖 =====

    /**
     * 删除有序数组中的重复项，LeetCode 26
     * slow 指向已去重区间末尾，fast 扫描新元素
     * 时间 O(n)，空间 O(1)
     */
    public static int removeDuplicates(int[] nums) {
        if (nums.length == 0) return 0;
        int slow = 0; // slow 左侧（含）均为不重复元素
        for (int fast = 1; fast < nums.length; fast++) {
            if (nums[fast] != nums[slow]) {
                slow++;
                nums[slow] = nums[fast]; // 新有效值写入 slow+1 位置
            }
        }
        return slow + 1; // 新数组长度
    }
}

public class SeparatedPointer {
    /**
     * 合并两个有序数组，LeetCode 88
     * nums1 长度为 m+n，前 m 个有效，nums2 长度为 n
     * 从后往前合并避免覆盖 nums1 未处理元素
     * 时间 O(m+n)，空间 O(1)
     */
    public static void merge(int[] nums1, int m, int[] nums2, int n) {
        int i = m - 1;     // nums1 有效元素末尾
        int j = n - 1;     // nums2 末尾
        int k = m + n - 1; // 合并位置末尾
        while (i >= 0 && j >= 0) {
            if (nums1[i] > nums2[j]) {
                nums1[k--] = nums1[i--]; // nums1[i] 更大，放到末尾
            } else {
                nums1[k--] = nums2[j--];
            }
        }
        // nums2 有剩余则拷贝；nums1 有剩余则已在原位
        while (j >= 0) {
            nums1[k--] = nums2[j--];
        }
    }
}
